"""Auth context adapters. Generated by tools/generate_auth_adapters.py; do not edit.

Each adapter maps claims your backend has already verified into the
`auth_context` of an assessment request. Pass verified claims, not a raw token.

The mapping is the claim map (contracts/api/v1/fixtures/assessment-contract/
auth-context-claim-map.json), run by the small interpreter below. Every SDK
runs the same table and the same vectors. A claim that is missing, mistyped or
out of range maps to absent, never to a stronger assurance.
"""

from __future__ import annotations

import datetime
import json
import math
import re
from typing import Any, Mapping, Optional

from .models.shared.authcontext import AuthContext

__all__ = ["from_workos", "from_clerk", "from_auth0", "from_oidc"]

_MAP = json.loads(
    r'''{"version":1,"kinds":{"id":{"pattern":"[A-Za-z0-9._:@/|+=~-]+","maxLength":256},"audience":{"pattern":"[A-Za-z0-9._:/-]+","maxLength":256},"role":{"pattern":"[A-Za-z0-9._:@/-]+","maxLength":64},"method":{"pattern":"[A-Za-z0-9._:-]+","maxLength":32},"issuer":{"pattern":"https://[\\x21-\\x7e]+","maxLength":256},"time":{"pattern":"[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])T([01][0-9]|2[0-3]):[0-5][0-9]:([0-5][0-9]|60)(\\.[0-9]+)?(Z|[+-]([01][0-9]|2[0-3]):[0-5][0-9])","maxLength":64}},"slug":"[a-z0-9][a-z0-9._-]{1,31}","constants":{"verified":true,"transport":"backend"},"base":{"issuer":{"op":"id","kind":"issuer","claims":["iss"],"required":true},"subject":{"op":"id","kind":"id","claims":["sub"],"required":true},"audiences":{"op":"list","kind":"audience","claims":["aud"],"split":"whitespace","max":8},"issued_at":{"op":"time","claims":["iat"]},"expires_at":{"op":"time","claims":["exp"]},"auth_time":{"op":"time","claims":["auth_time"]},"session_id":{"op":"id","kind":"id","claims":["sid"]},"token_id":{"op":"id","kind":"id","claims":["jti"]}},"providers":{"workos":{"fields":{"organization_id":{"op":"id","kind":"id","claims":["org_id"]},"roles":{"op":"list","kind":"role","claims":["roles","role"],"split":"whitespace","max":32},"scopes":{"op":"list","kind":"role","claims":["permissions"],"split":"whitespace","max":32},"impersonated":{"op":"actor","claims":["act"]}}},"clerk":{"disable":["issued_at"],"fields":{"organization_id":{"op":"id","kind":"id","claims":["o.id","org_id"]},"roles":{"op":"list","kind":"role","claims":["o.rol","org_role"],"split":"none","max":32},"scopes":{"op":"list","kind":"role","claims":["o.per","org_permissions"],"split":"comma_whitespace","max":32},"impersonated":{"op":"actor","claims":["act"]},"mfa":{"op":"mfa_factor_age","claim":"fva","index":1,"unitSeconds":60,"maxSeconds":315360000}}},"auth0":{"fields":{"organization_id":{"op":"id","kind":"id","claims":["org_id"]},"scopes":{"op":"list","kind":"role","claims":["scope","permissions"],"split":"whitespace","max":32},"email_verified":{"op":"bool","claims":["email_verified"]},"phone_verified":{"op":"bool","claims":["phone_number_verified"]},"impersonated":{"op":"actor","claims":["act"]},"mfa":{"op":"mfa_methods","kind":"method","claim":"amr","max":8,"mfaValue":"mfa","ignore":["pwd"]}}},"oidc":{"slugArgument":true,"fields":{}}}}'''
)
_KINDS = {
    name: (re.compile("(?:" + kind["pattern"] + ")"), kind["maxLength"])
    for name, kind in _MAP["kinds"].items()
}
_SLUG = re.compile("(?:" + _MAP["slug"] + ")")
_SPLITTERS = {
    "whitespace": re.compile(r"[ \t\r\n\f\v]+"),
    "comma_whitespace": re.compile(r"[ \t\r\n\f\v,]+"),
}
_MAX_TIME = 253402300799


def _lookup(claims: Mapping[str, Any], path: str) -> Any:
    current: Any = claims
    for key in path.split("."):
        if not isinstance(current, Mapping) or key not in current:
            return None
        current = current[key]
    return current


def _number(value: Any) -> bool:
    return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value)


def _matches(kind: str, value: Any) -> bool:
    pattern, limit = _KINDS[kind]
    return isinstance(value, str) and len(value) <= limit and pattern.fullmatch(value) is not None


def _lower(value: str) -> str:
    return "".join(chr(ord(c) + 32) if "A" <= c <= "Z" else c for c in value)


def _map_time(claims: Mapping[str, Any], rule: Mapping[str, Any]) -> Optional[str]:
    for path in rule["claims"]:
        value = _lookup(claims, path)
        if _number(value) and 0 <= value <= _MAX_TIME:
            # Whole UTC seconds; the fraction is truncated.
            moment = datetime.datetime.fromtimestamp(int(value), datetime.timezone.utc)
            return moment.strftime("%Y-%m-%dT%H:%M:%SZ")
        if _matches("time", value):
            return value
    return None


def _map_list(claims: Mapping[str, Any], rule: Mapping[str, Any]) -> Optional[list]:
    for path in rule["claims"]:
        value = _lookup(claims, path)
        items: list = []
        if isinstance(value, str):
            items = [value] if rule.get("split") == "none" else _SPLITTERS[rule.get("split", "whitespace")].split(value)
        elif isinstance(value, list):
            items = value
        kept = [item for item in items if _matches(rule["kind"], item)][: rule["max"]]
        if kept:
            return kept
    return None


def _map_rule(claims: Mapping[str, Any], rule: Mapping[str, Any]) -> Any:
    op = rule["op"]
    if op == "id":
        for path in rule["claims"]:
            value = _lookup(claims, path)
            if _matches(rule["kind"], value):
                return value
        return None
    if op == "list":
        return _map_list(claims, rule)
    if op == "time":
        return _map_time(claims, rule)
    if op == "bool":
        for path in rule["claims"]:
            value = _lookup(claims, path)
            if isinstance(value, bool):
                return value
        return None
    if op == "actor":
        value = _lookup(claims, rule["claims"][0])
        if isinstance(value, Mapping):
            return any(isinstance(value.get(key), str) and len(value[key]) > 0 for key in ("sub", "email"))
        return isinstance(value, str) and len(value) > 0
    if op == "mfa_factor_age":
        value = _lookup(claims, rule["claim"])
        age = value[rule["index"]] if isinstance(value, list) and len(value) > rule["index"] else None
        if not _number(age):
            return None
        seconds = age * rule["unitSeconds"]
        if 0 <= seconds <= rule["maxSeconds"]:
            return {"present": True, "age_seconds": int(seconds)}
        return None
    if op == "mfa_methods":
        value = _lookup(claims, rule["claim"])
        if not isinstance(value, list):
            return None
        kept = [item for item in value if _matches(rule["kind"], item)][: rule["max"]]
        methods = [item for item in kept if _lower(item) not in rule["ignore"]]
        if not methods:
            return None
        return {"present": any(_lower(item) == rule["mfaValue"] for item in kept), "methods": methods}
    raise ValueError("unknown claim map op " + op)


def _build(
    name: str,
    provider: str,
    claims: Mapping[str, Any],
    overrides: Optional[Mapping[str, Any]],
) -> AuthContext:
    spec = _MAP["providers"][name]
    rules = {**_MAP["base"], **spec["fields"]}
    for field in spec.get("disable", []):
        rules.pop(field, None)
    wire: dict = {"provider": provider, **_MAP["constants"]}
    for field, rule in rules.items():
        value = _map_rule(claims, rule)
        if value is not None:
            wire[field] = value
    for field, value in (overrides or {}).items():
        if value is not None:
            wire[field] = value
    audiences = wire.get("audiences")
    if isinstance(audiences, list) and audiences and "audience" not in wire:
        wire["audience"] = audiences[0]
    if not wire.get("issuer") or not wire.get("subject"):
        raise ValueError("NoResponse auth context requires a verified issuer and subject")
    return AuthContext.model_validate(wire)


def from_workos(claims: Mapping[str, Any], overrides: Optional[Mapping[str, Any]] = None) -> AuthContext:
    """Map verified WorkOS AuthKit claims plus verified user or session record overrides.

    Overrides use the auth_context field names, for example `email_verified`.
    """
    return _build("workos", "workos", claims, overrides)


def from_clerk(claims: Mapping[str, Any], overrides: Optional[Mapping[str, Any]] = None) -> AuthContext:
    """Map verified Clerk session claims. Pass Session.created_at as `session_created_at`."""
    return _build("clerk", "clerk", claims, overrides)


def from_auth0(claims: Mapping[str, Any], overrides: Optional[Mapping[str, Any]] = None) -> AuthContext:
    """Map verified Auth0 ID token, userinfo or normalised session claims.

    Do not pass an opaque API access token.
    """
    return _build("auth0", "auth0", claims, overrides)


def from_oidc(provider: str, claims: Mapping[str, Any], overrides: Optional[Mapping[str, Any]] = None) -> AuthContext:
    """Generic OIDC adapter for providers without a first-class helper. `provider` is a lowercase slug."""
    if not isinstance(provider, str) or _SLUG.fullmatch(provider) is None:
        raise ValueError("provider must be a lowercase provider slug")
    return _build("oidc", provider, claims, overrides)
